        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_TryWaitSemaphore">SDL_TryWaitSemaphore</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Semaphore.Signal">Signal</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.Wait">Wait</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.WaitTimeout">WaitTimeout</see></seealso>
        public static extern void TryWaitSemaphore();

        /// <summary>
        /// <para>Unlock the mutex.</para>
        /// </summary>
        /// <remarks>
        /// <para>It is legal for the owning thread to lock an already-locked mutex. It must unlock it the same number of times before it is actually made available for other threads in the system (this is known as a "recursive mutex").</para>
        /// <para>It is illegal to unlock a mutex that has not been locked by the current thread, and doing so results in undefined behavior.</para>
        /// </remarks>
        /// <param name="mutex">the mutex to unlock.</param>
        /// <threadsafety>This call must be paired with a previous locking call on the same thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnlockMutex">SDL_UnlockMutex</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Mutex.Lock">Lock</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Mutex.TryLock">TryLock</see></seealso>
        public static extern void UnlockMutex();

        /// <summary>
        /// <para>Unlock the read/write lock.</para>
        /// </summary>
        /// <remarks>
        /// <para>Use this function to unlock the rwlock, whether it was locked for read-only or write operations.</para>
        /// <para>It is legal for the owning thread to lock an already-locked read-only lock. It must unlock it the same number of times before it is actually made available for other threads in the system (this is known as a "recursive rwlock").</para>
        /// <para>It is illegal to unlock a rwlock that has not been locked by the current thread, and doing so results in undefined behavior.</para>
        /// </remarks>
        /// <param name="rwlock">the rwlock to unlock.</param>
        /// <threadsafety>This call must be paired with a previous locking call on the same thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_UnlockRWLock">SDL_UnlockRWLock</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.RWLock.LockForReading">LockForReading</see></seealso>
        /// <seealso><see cref="CSDL.Threads.RWLock.LockForWriting">LockForWriting</see></seealso>
        /// <seealso><see cref="CSDL.Threads.RWLock.TryLockForReading">TryLockForReading</see></seealso>
        /// <seealso><see cref="CSDL.Threads.RWLock.TryLockForWriting">TryLockForWriting</see></seealso>
        public static extern void UnlockRWLock();

        /// <summary>
        /// <para>Wait until a condition variable is signaled.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function unlocks the specified <c>mutex</c> and waits for another thread to call <see cref="CSDL.Threads.Condition.Signal">Signal</see> or <see cref="CSDL.Threads.Condition.Broadcast">Broadcast</see> on the condition variable <c>cond</c>. Once the condition variable is signaled, the mutex is re-locked and the function returns.</para>
        /// <para>The mutex must be locked before calling this function. Locking the mutex recursively (more than once) is not supported and leads to undefined behavior.</para>
        /// <para>This function is the equivalent of calling <see cref="CSDL.Threads.Condition.WaitTimeout">WaitTimeout</see> with a time length of -1.</para>
        /// </remarks>
        /// <param name="cond">the condition variable to wait on.</param>
        /// <param name="mutex">the mutex used to coordinate thread access.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitCondition">SDL_WaitCondition</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Condition.Broadcast">Broadcast</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Condition.Signal">Signal</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Condition.WaitTimeout">WaitTimeout</see></seealso>
        public static extern void WaitCondition();

        /// <summary>
        /// <para>Wait until a condition variable is signaled or a certain time has passed.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function unlocks the specified <c>mutex</c> and waits for another thread to call <see cref="CSDL.Threads.Condition.Signal">Signal</see> or <see cref="CSDL.Threads.Condition.Broadcast">Broadcast</see> on the condition variable <c>cond</c>, or for the specified time to elapse. Once the condition variable is signaled or the time elapsed, the mutex is re-locked and the function returns.</para>
        /// <para>The mutex must be locked before calling this function. Locking the mutex recursively (more than once) is not supported and leads to undefined behavior.</para>
        /// </remarks>
        /// <param name="cond">the condition variable to wait on.</param>
        /// <param name="mutex">the mutex used to coordinate thread access.</param>
        /// <param name="timeoutMS">the maximum time to wait, in milliseconds, or -1 to wait indefinitely.</param>
        /// <returns>
        /// <para>(bool) Returns true if the condition variable is signaled, false if the condition is not signaled in the allotted time.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitConditionTimeout">SDL_WaitConditionTimeout</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Condition.Broadcast">Broadcast</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Condition.Signal">Signal</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Condition.Wait">Wait</see></seealso>
        public static extern void WaitConditionTimeout();

        /// <summary>
        /// <para>Wait until a semaphore has a positive value and then decrements it.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function suspends the calling thread until the semaphore pointed to by <c>sem</c> has a positive value, and then atomically decrement the semaphore value.</para>
        /// <para>This function is the equivalent of calling <see cref="CSDL.Threads.Semaphore.WaitTimeout">WaitTimeout</see> with a time length of -1.</para>
        /// </remarks>
        /// <param name="sem">the semaphore wait on.</param>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitSemaphore">SDL_WaitSemaphore</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Semaphore.Signal">Signal</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.TryWait">TryWait</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.WaitTimeout">WaitTimeout</see></seealso>
        public static extern void WaitSemaphore();

        /// <summary>
        /// <para>Wait until a semaphore has a positive value and then decrements it.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function suspends the calling thread until either the semaphore pointed to by <c>sem</c> has a positive value or the specified time has elapsed. If the call is successful it will atomically decrement the semaphore value.</para>
        /// </remarks>
        /// <param name="sem">the semaphore to wait on.</param>
        /// <param name="timeoutMS">the length of the timeout, in milliseconds, or -1 to wait indefinitely.</param>
        /// <returns>
        /// <para>(bool) Returns true if the wait succeeds or false if the wait times out.</para>
        /// </returns>
        /// <threadsafety>It is safe to call this function from any thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WaitSemaphoreTimeout">SDL_WaitSemaphoreTimeout</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Threads.Semaphore.Signal">Signal</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.TryWait">TryWait</see></seealso>
        /// <seealso><see cref="CSDL.Threads.Semaphore.Wait">Wait</see></seealso>
        public static extern void WaitSemaphoreTimeout();
    }
}
